  '<head>',
  '<head>\n    <script src="/assets/api-mock.js"></script>'
);
fs.writeFileSync(path.join(distDir, 'chatgpt', 'index.html'), chatgptHtml);
console.log('Generated dist/chatgpt/index.html');

// 7. Prepare /articles/index.html and its assets
